// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Record the initial owner (set by constructor to deployer)
        address initialOwner = c.smartfix_owner();
        // Drive the call
        c.sudicideAnyone();
        // After selfdestruct, the contract is empty. Check if the address(c).balance is 0;
        // also the getter for smartfix_owner may revert or return address(0).
        // The rule: after call, the contract's balance is 0 (since it's destroyed).
        assertTrue(address(c).balance == 0);
    }
}

